//! Exact protocol/serialization/version-string fixtures generated by the pinned TypeScript
//! reference.

use std::collections::BTreeMap;
use std::error::Error;
use std::str::FromStr;

use keri_protocol::event::kind::EventKind;
use keri_protocol::serialization::{Protocol, ProtocolVersion, SerializationKind, VersionError, VersionString};
use serde::Deserialize;

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    constants: Constants,
    ilks: BTreeMap<String, String>,
    default_versify: DefaultVersify,
    versify_cases: Vec<VersifyCase>,
    deversify_cases: Vec<DeversifyCase>,
    rejected_cases: Vec<RejectedCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct Constants {
    verfullsize: usize,
    minsniffsize: usize,
    minsigsize: usize,
    verex: String,
    protocols: Vec<String>,
    serializations: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct DefaultVersify {
    no_arguments: String,
    acdc_defaults: String,
}

#[derive(Debug, Deserialize)]
struct VersifyCase {
    name: String,
    protocol: String,
    major: u8,
    minor: u8,
    kind: String,
    size: u32,
    output: String,
}

#[derive(Debug, Deserialize)]
struct DeversifyCase {
    name: String,
    input: String,
    protocol: String,
    kind: String,
    major: String,
    minor: String,
    size_hex: String,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    input: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    unanchored_match: UnanchoredMatchQuirk,
    hex_digit_decimal_coercion: HexDigitQuirk,
    aliased_version_objects: AliasedVersionQuirk,
    shared_default_version_mutation: SharedDefaultQuirk,
    size_overflow_emission: EmissionQuirk,
    negative_size_emission: NegativeEmissionQuirk,
    major_overflow_emission: MajorEmissionQuirk,
}

#[derive(Debug, Deserialize)]
struct UnanchoredMatchQuirk {
    input: String,
    protocol: String,
    kind: String,
    size_hex: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct HexDigitQuirk {
    input: String,
    major: String,
    minor: String,
    rust_major: u8,
    note: String,
}

#[derive(Debug, Deserialize)]
struct AliasedVersionQuirk {
    inputs: Vec<String>,
    all_returns_are_one_object: bool,
    note: String,
}

#[derive(Debug, Deserialize)]
struct SharedDefaultQuirk {
    input: String,
    returns_shared_singleton: bool,
    default_versify_after_parse: String,
    note: String,
}

#[derive(Debug, Deserialize)]
struct EmissionQuirk {
    size: u32,
    output: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct NegativeEmissionQuirk {
    size: i64,
    output: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct MajorEmissionQuirk {
    major: u8,
    output: String,
    rust_error_category: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/version/v1.json"
    )))?)
}

fn error_category(error: &VersionError) -> &'static str {
    match error {
        VersionError::InvalidLength { .. } => "InvalidLength",
        VersionError::UnsupportedProtocol { .. } => "UnsupportedProtocol",
        VersionError::UnsupportedSerialization { .. } => "UnsupportedSerialization",
        VersionError::InvalidVersionDigit { .. } => "InvalidVersionDigit",
        VersionError::InvalidSizeDigit => "InvalidSizeDigit",
        VersionError::MissingTerminator => "MissingTerminator",
        VersionError::VersionComponentOutOfRange { .. } => "VersionComponentOutOfRange",
        VersionError::SizeOutOfRange { .. } => "SizeOutOfRange",
        _ => "Unknown",
    }
}

#[test]
fn fixture_metadata_and_constants_match_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(fixture.sources, ["src/keri/core/core.ts", "test/core/serder.test.ts"]);

    assert_eq!(fixture.constants.verfullsize, VersionString::FULL_SIZE);
    // MINSNIFFSIZE and MINSIGSIZE have no consumer in the pinned reference; they are recorded
    // here and become Rust constants with their first real consumer.
    assert_eq!(fixture.constants.minsniffsize, 12 + VersionString::FULL_SIZE);
    assert_eq!(fixture.constants.minsigsize, 4);
    assert!(fixture.constants.verex.starts_with("(KERI|ACDC)"));

    let protocols: Vec<&str> = Protocol::ALL.iter().map(|p| p.as_str()).collect();
    assert_eq!(fixture.constants.protocols, protocols);
    let kinds: Vec<&str> = SerializationKind::ALL.iter().map(|k| k.as_str()).collect();
    assert_eq!(fixture.constants.serializations, kinds);
    Ok(())
}

#[test]
fn every_reference_ilk_round_trips_and_the_table_is_complete() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    // Rust's table is the reference's plus `qry`, which keripy declares and signify-ts does not.
    assert_eq!(fixture.ilks.len() + 1, EventKind::ALL.len());
    for (key, value) in &fixture.ilks {
        assert_eq!(key, value, "reference ilk key/value mismatch for {key}");
        let kind = EventKind::from_str(value)?;
        assert_eq!(kind.as_str(), value);
    }
    for kind in EventKind::ALL {
        assert!(
            fixture.ilks.contains_key(kind.as_str()) || kind == EventKind::Query,
            "Rust ilk {} is not in the reference table",
            kind.as_str()
        );
    }
    Ok(())
}

#[test]
fn versify_cases_format_and_reparse_exactly() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.default_versify.no_arguments, "KERI10JSON000000_");
    assert_eq!(fixture.default_versify.acdc_defaults, "ACDC10JSON000000_");

    for case in &fixture.versify_cases {
        let protocol = Protocol::from_str(&case.protocol)?;
        let kind = SerializationKind::from_str(&case.kind)?;
        let version = ProtocolVersion::new(case.major, case.minor)?;
        let built = VersionString::new(protocol, version, kind, case.size)?;
        assert_eq!(built.to_string(), case.output, "case {}", case.name);
        assert_eq!(built.to_string().len(), VersionString::FULL_SIZE);

        let reparsed = VersionString::from_str(&case.output)?;
        assert_eq!(reparsed, built, "round trip for case {}", case.name);
    }
    Ok(())
}

#[test]
fn deversify_cases_parse_every_field_exactly() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for case in &fixture.deversify_cases {
        let parsed = VersionString::from_str(&case.input)?;
        assert_eq!(parsed.protocol().as_str(), case.protocol, "case {}", case.name);
        assert_eq!(parsed.kind().as_str(), case.kind, "case {}", case.name);
        assert_eq!(
            u8::from_str(&case.major)?,
            parsed.version().major(),
            "case {}",
            case.name
        );
        assert_eq!(
            u8::from_str(&case.minor)?,
            parsed.version().minor(),
            "case {}",
            case.name
        );
        assert_eq!(
            u32::from_str_radix(&case.size_hex, 16)?,
            parsed.size(),
            "case {}",
            case.name
        );
        assert_eq!(parsed.to_string(), case.input, "case {}", case.name);
    }
    Ok(())
}

#[test]
fn reference_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    for case in &fixture.rejected_cases {
        assert_ne!(case.reference_error_message, "");
        match VersionString::from_str(&case.input) {
            Err(error) => assert_eq!(error_category(&error), case.rust_error_category, "case {}", case.name),
            Ok(parsed) => assert!(
                parsed.to_string().is_empty(),
                "case {} unexpectedly parsed as {parsed}",
                case.name
            ),
        }
    }
    Ok(())
}

#[test]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // The reference accepts embedded version strings; Rust anchors the full seventeen bytes.
    let unanchored = &quirks.unanchored_match;
    assert_eq!(unanchored.protocol, "KERI");
    assert_eq!(unanchored.kind, "JSON");
    assert_eq!(unanchored.size_hex, "00011c");
    match VersionString::from_str(&unanchored.input) {
        Err(error) => assert_eq!(error_category(&error), unanchored.rust_error_category),
        Ok(parsed) => assert!(
            parsed.to_string().is_empty(),
            "embedded input unexpectedly parsed as {parsed}"
        ),
    }

    // The reference coerces hexadecimal digits decimally; Rust parses them as hexadecimal.
    let coercion = &quirks.hex_digit_decimal_coercion;
    assert_eq!(coercion.major, "NaN");
    assert_eq!(coercion.minor, "0");
    assert_ne!(coercion.note, "");
    let parsed = VersionString::from_str(&coercion.input)?;
    assert_eq!(parsed.version().major(), coercion.rust_major);
    assert_eq!(parsed.version().minor(), 0);

    // The reference aliases and mutates one shared Version object; Rust values are immutable, so
    // a parse can never change a later default.
    assert!(quirks.aliased_version_objects.all_returns_are_one_object);
    assert_eq!(quirks.aliased_version_objects.inputs.len(), 3);
    assert_ne!(quirks.aliased_version_objects.note, "");
    let mutation = &quirks.shared_default_version_mutation;
    assert!(mutation.returns_shared_singleton);
    assert_eq!(mutation.default_versify_after_parse, mutation.input);
    assert_ne!(mutation.note, "");
    let before = VersionString::new(Protocol::Keri, ProtocolVersion::V1_0, SerializationKind::Json, 0)?;
    let _ = VersionString::from_str(&mutation.input)?;
    let after = VersionString::new(Protocol::Keri, ProtocolVersion::V1_0, SerializationKind::Json, 0)?;
    assert_eq!(before, after);
    assert_eq!(after.to_string(), fixture.default_versify.no_arguments);

    // The reference emits invalid overlong or non-hexadecimal strings for out-of-range inputs;
    // Rust rejects those states at construction, and also rejects the emitted text.
    let overflow = &quirks.size_overflow_emission;
    assert_eq!(overflow.output.len(), VersionString::FULL_SIZE + 1);
    assert!(matches!(
        VersionString::new(
            Protocol::Keri,
            ProtocolVersion::V1_0,
            SerializationKind::Json,
            overflow.size,
        ),
        Err(VersionError::SizeOutOfRange { .. })
    ));
    assert_eq!(overflow.rust_error_category, "SizeOutOfRange");
    assert!(VersionString::from_str(&overflow.output).is_err());

    let negative = &quirks.negative_size_emission;
    assert!(negative.size < 0, "negative-size quirk must record a negative size");
    assert_eq!(negative.rust_error_category, "Unrepresentable");
    assert!(u32::try_from(negative.size).is_err());
    assert!(VersionString::from_str(&negative.output).is_err());

    let major = &quirks.major_overflow_emission;
    assert!(matches!(
        ProtocolVersion::new(major.major, 0),
        Err(VersionError::VersionComponentOutOfRange { .. })
    ));
    assert_eq!(major.rust_error_category, "VersionComponentOutOfRange");
    assert!(VersionString::from_str(&major.output).is_err());
    Ok(())
}
